entries[190765] = { ["name"] = "Iska's Mawrat Leash", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Colossal Mawrat.\nSummons and dismisses your Colossal Plaguespew Mawrat.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"These rodents became Iska's infamous sentries, scouting and carrying her plague across the Maw. Their presence is only followed by ruin.\"\nDrop:\nRhuv, Gorger of Ruin" }
entries[190766] = { ["name"] = "Spectral Mawrat's Tail", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a Colossal Mawrat.\nSummons and dismisses your Colossal Wraithbound Mawrat.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Infused by the energies of tormented souls, these creatures have adopted ghostlike abilities that make them quite elusive.\"\nDrop:\nMawsworn Supply Chest" }
entries[190767] = { ["name"] = "Armored Golden Pterrordax", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Painted and adorned with gold, these Pterrordax patrol the skies over the tomb of Atal'Dazar.\"\nTrading Post" }
entries[190768] = { ["name"] = "Fractal Cypher of the Zereth Overseer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Enigmatic and aloof, this construct of the First Ones flies on a graceful stream of perfect geometric understanding.\"\nDrop:\nThe Jailer\nZone:\nSepulcher of the First Ones\nDifficulty:\nMythic" }
entries[190769] = { ["name"] = "Unstable Arcana", ["text"] = "Quest Item\n\"Unstable arcana condensed into a gem. Looks ready to explode at any moment... so don't shake it around too much.\"" }
entries[190771] = { ["name"] = "Fractal Cypher of the Carcinized Zerethsteed", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The few of these mysterious creatures that remain appear to be impossibly old, almost timeless. Perhaps they were created by the First Ones, because no schematic to synthesize these has yet been discovered.\"\nQuest:\nLeading Motives" }
