entries[191566] = { ["name"] = "Elusive Emerald Hawkstrider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Unseen for many years, this brightly hued hawkstrider emerged from hiding to help defend the Ghostlands from the Scourge. Its prowess shines as brilliantly as its feathers.\"\nQuest:\nBlood Knight\nZone:\nGhostlands\n\nQuest:\nVictory for the Sin'dorei\nZone:\nGhostlands" }
