entries[191583] = { ["name"] = "Recipe: Transmute: Order to Elements", ["text"] = "Binds when picked up\nUse: Teaches you how to transmute a variety of stable awakened elements from Awakened Order.\nDestroy a random element from the core of an Awakened Order, revealing the three remaining elements in the process.\nRequires Dragon Isles Alchemy (25)\nSell Price:\nOrder to Elements\n\"Destroy a random element from the core of an Awakened Order, revealing the three remaining elements in the process.\"\nRequires Awakened Order" }
