entries[192299] = { ["name"] = "Eternal Gladiator's Relentless Brooch", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+28 [Agility or Strength or Intellect]\nEquip: Duration of incoming crowd control effects reduced by 20%. Does not stack with similar effects.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[192300] = { ["name"] = "Eternal Gladiator's Sigil of Adaptation", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+28 [Agility or Strength or Intellect]\nEquip: Removes any loss of control effect with a duration of 5 seconds or more. This effect can only occur once every 1 min.\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion\n(2) Set : Increases your Primary Stat by 12% and your Stamina by 20% when in Arenas, Battlegrounds, and War Mode.\nSell Price:" }
entries[192301] = { ["name"] = "Eternal Gladiator's Fastidious Resolve", ["text"] = "Binds when picked up\nUnique-Equipped: Gladiator's Medallions (1)\nTrinket\n+28 [Agility or Strength or Intellect]\nUse: Activate the Broker defenses, protecting yourself from spell interruption and crowd control effects. The defenses withstand up to 2 effects and persist for 12 sec.\nSell Price:" }
